//! Lattice hash (Agave's `AccountsLtHash`) — the primary checksum over snapshot
//! account data.
//!
//! Agave reference:
//! https://github.com/anza-xyz/agave/blob/master/lattice-hash/src/lt_hash.rs
//!
//! Ported from the v1 implementation (`v1/src/core/hash.zig` and
//! `v1/src/core/account.zig`), whose output is verified against Agave. The
//! per-account digest layout and the element ordering are covered by
//! `test "accounts_lt_hash matches agave snapshot"` in `snapshot.zig`, which
//! checks it against a snapshot generated by Agave.
//!
//! TODO(#1727): wire this into snapshot loading. See `docs/upstream-issues-todo.md`.

const std = @import("std");
const solana = @import("../solana.zig");

const Hash = solana.Hash;
const Pubkey = solana.Pubkey;

pub const LtHash = struct {
    data: [NUM_ELEMENTS]u16,

    pub const NUM_ELEMENTS: usize = 1024;
    pub const BYTES_LEN: usize = NUM_ELEMENTS * @sizeOf(u16);

    pub const IDENTITY: LtHash = .{ .data = @splat(0) };

    const vec_len = std.simd.suggestVectorLength(u16) orelse 4;
    const Vector = @Vector(vec_len, u16);

    comptime {
        std.debug.assert(@sizeOf(LtHash) == BYTES_LEN);
        std.debug.assert(NUM_ELEMENTS % vec_len == 0);
    }

    /// Decodes an element array from its little-endian byte form.
    pub fn fromBytes(raw: *const [BYTES_LEN]u8) LtHash {
        var self: LtHash = undefined;
        for (&self.data, 0..) |*element, i| {
            element.* = std.mem.readInt(u16, raw[i * 2 ..][0..2], .little);
        }
        return self;
    }

    pub fn bytes(self: *LtHash) []u8 {
        return std.mem.asBytes(&self.data);
    }

    pub fn constBytes(self: *const LtHash) []const u8 {
        return std.mem.asBytes(&self.data);
    }

    /// Mixes `other` into `self`, equivalent to inserting an account.
    pub fn mixIn(self: *LtHash, other: LtHash) void {
        self.* = self.add(other);
    }

    /// Mixes `other` out of `self`, equivalent to removing an account.
    pub fn mixOut(self: *LtHash, other: LtHash) void {
        self.* = self.sub(other);
    }

    pub fn add(lhs: LtHash, rhs: LtHash) LtHash {
        var data: [NUM_ELEMENTS]u16 = undefined;
        inline for (0..NUM_ELEMENTS / vec_len) |n| {
            const lhs_v: Vector = lhs.data[n * vec_len ..][0..vec_len].*;
            const rhs_v: Vector = rhs.data[n * vec_len ..][0..vec_len].*;
            data[n * vec_len ..][0..vec_len].* = lhs_v +% rhs_v;
        }
        return .{ .data = data };
    }

    pub fn sub(lhs: LtHash, rhs: LtHash) LtHash {
        var data: [NUM_ELEMENTS]u16 = undefined;
        inline for (0..NUM_ELEMENTS / vec_len) |n| {
            const lhs_v: Vector = lhs.data[n * vec_len ..][0..vec_len].*;
            const rhs_v: Vector = rhs.data[n * vec_len ..][0..vec_len].*;
            data[n * vec_len ..][0..vec_len].* = lhs_v -% rhs_v;
        }
        return .{ .data = data };
    }

    pub fn eql(lhs: LtHash, rhs: LtHash) bool {
        return std.mem.eql(u16, &lhs.data, &rhs.data);
    }

    /// Collapses the 2KiB lattice into a single hash, as Agave does when a
    /// `Hash` is more convenient than the full LtHash.
    pub fn checksum(self: LtHash) Hash {
        var out: Hash = undefined;
        std.crypto.hash.Blake3.hash(self.constBytes(), &out.data, .{});
        return out;
    }

    /// Incrementally computes one account's contribution to the lattice hash.
    ///
    /// The digest covers `lamports (u64 LE) || data || executable (u8) || owner
    /// || pubkey`, in that order. Since the data sits in the middle, callers
    /// pass the fields preceding it to `init`, stream the data through
    /// `update`, and close the digest with `final`. This lets the snapshot
    /// loader hash account data while reading it from disk instead of buffering
    /// accounts up to 10MiB in size.
    pub const AccountHasher = struct {
        hasher: std.crypto.hash.Blake3,
        executable: bool,
        owner: Pubkey,
        address: Pubkey,
        /// Zero-lamport accounts contribute the identity element, so their data
        /// is never fed to the hasher.
        identity: bool,

        pub fn init(
            lamports: u64,
            owner: *const Pubkey,
            executable: bool,
            address: *const Pubkey,
        ) AccountHasher {
            var self: AccountHasher = .{
                .hasher = std.crypto.hash.Blake3.init(.{}),
                .executable = executable,
                .owner = owner.*,
                .address = address.*,
                .identity = lamports == 0,
            };
            if (!self.identity) {
                var lamports_buf: [@sizeOf(u64)]u8 = undefined;
                std.mem.writeInt(u64, &lamports_buf, lamports, .little);
                self.hasher.update(&lamports_buf);
            }
            return self;
        }

        /// Streams the next chunk of the account's data. Chunks may be of any
        /// size and are equivalent to a single call with the concatenation.
        pub fn update(self: *AccountHasher, data: []const u8) void {
            if (self.identity) return;
            self.hasher.update(data);
        }

        /// Closes the digest. Must be called exactly once.
        pub fn final(self: *AccountHasher) LtHash {
            if (self.identity) return IDENTITY;

            self.hasher.update(&[_]u8{@intFromBool(self.executable)});
            self.hasher.update(&self.owner.data);
            self.hasher.update(&self.address.data);

            var digest: [BYTES_LEN]u8 = undefined;
            self.hasher.final(&digest);
            return fromBytes(&digest);
        }
    };

    /// Computes one account's contribution to the lattice hash.
    ///
    /// Field order and encoding must match Agave exactly:
    /// `lamports (u64 LE) || data || executable (u8) || owner || pubkey`,
    /// hashed with blake3 in extendable-output mode for `BYTES_LEN` bytes.
    /// `rent_epoch` is deliberately excluded. Accounts with zero lamports do
    /// not contribute, which Agave models as the identity element.
    pub fn hashAccount(
        lamports: u64,
        data: []const u8,
        owner: *const Pubkey,
        executable: bool,
        address: *const Pubkey,
    ) LtHash {
        var hasher = AccountHasher.init(lamports, owner, executable, address);
        hasher.update(data);
        return hasher.final();
    }
};

test "identity" {
    var rng = std.Random.DefaultPrng.init(std.testing.random_seed);
    var a: LtHash = .{ .data = undefined };
    rng.random().bytes(a.bytes());

    try std.testing.expect(a.eql(a.add(LtHash.IDENTITY)));
    try std.testing.expect(a.eql(a.sub(LtHash.IDENTITY)));
}

test "mix in then out is a no-op" {
    var rng = std.Random.DefaultPrng.init(std.testing.random_seed);
    var a: LtHash = .{ .data = undefined };
    var b: LtHash = .{ .data = undefined };
    rng.random().bytes(a.bytes());
    rng.random().bytes(b.bytes());

    const before = a;
    a.mixIn(b);
    a.mixOut(b);
    try std.testing.expect(before.eql(a));
}

test "byte round trip is little endian" {
    var rng = std.Random.DefaultPrng.init(std.testing.random_seed);
    var original: LtHash = .{ .data = undefined };
    rng.random().bytes(original.bytes());

    var bytes: [LtHash.BYTES_LEN]u8 = undefined;
    @memcpy(&bytes, original.constBytes());

    // The first element must be encoded least-significant byte first.
    try std.testing.expectEqual(original.data[0] & 0xff, bytes[0]);
    try std.testing.expectEqual(original.data[0] >> 8, bytes[1]);

    try std.testing.expect(original.eql(.fromBytes(&bytes)));
}

test "zero lamports contribute nothing" {
    const pubkey: Pubkey = .ZEROES;
    const zero = LtHash.hashAccount(0, "data", &pubkey, false, &pubkey);
    try std.testing.expect(zero.eql(LtHash.IDENTITY));

    const nonzero = LtHash.hashAccount(1, "data", &pubkey, false, &pubkey);
    try std.testing.expect(!nonzero.eql(LtHash.IDENTITY));
}

test "streaming account hasher matches one-shot hash" {
    var rng = std.Random.DefaultPrng.init(std.testing.random_seed);
    const random = rng.random();

    var owner: Pubkey = .ZEROES;
    var address: Pubkey = .ZEROES;
    random.bytes(&owner.data);
    random.bytes(&address.data);

    var data: [5_000]u8 = undefined;
    random.bytes(&data);

    inline for (.{ 1_000, 0 }) |lamports| {
        const expected = LtHash.hashAccount(lamports, &data, &owner, true, &address);

        var hasher = LtHash.AccountHasher.init(lamports, &owner, true, &address);
        var pos: usize = 0;
        // Uneven chunk sizes make sure no implicit alignment is assumed.
        for ([_]usize{ 3, 1, 512, 7, 997 }) |chunk_len| {
            const end = @min(pos + chunk_len, data.len);
            hasher.update(data[pos..end]);
            pos = end;
        }
        hasher.update(data[pos..]);

        try std.testing.expect(expected.eql(hasher.final()));
    }
}
